import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = read();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        long th = nextLong();
        String[] ids = new String[n];
        long[] times = new long[n];
        Integer[] order = new Integer[n];
        for (int i = 0; i < n; i++) {
            times[i] = nextLong();
            ids[i] = next();
            order[i] = i;
        }
        // Sorting (service, timestamp) pairs makes each service's heartbeats contiguous and in time order.
        Arrays.sort(order, (x, y) -> {
            int c = ids[x].compareTo(ids[y]);
            return c != 0 ? c : Long.compare(times[x], times[y]);
        });
        List<String> res = new ArrayList<>();
        for (int k = 1; k < n; k++) {
            int prev = order[k - 1], cur = order[k];
            if (ids[cur].equals(ids[prev]) && times[cur] - times[prev] > th
                    && (res.isEmpty() || !res.get(res.size() - 1).equals(ids[cur])))
                res.add(ids[cur]);
        }
        StringBuilder sb = new StringBuilder().append(res.size()).append('\n');
        for (String s : res) sb.append(s).append('\n');
        System.out.print(sb);
    }
}

package main

import (
	"cmp"
	"io"
	"os"
	"slices"
	"strconv"
)

var data []byte
var pos int

func skip() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func nextInt() int64 {
	skip()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func nextToken() string {
	skip()
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return string(data[start:pos])
}

type beat struct {
	id string
	t  int64
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := int(nextInt())
	th := nextInt()
	a := make([]beat, n)
	for i := range a {
		a[i].t = nextInt()
		a[i].id = nextToken()
	}
	// Sorting (service, timestamp) pairs makes each service's heartbeats contiguous and in time order.
	slices.SortFunc(a, func(x, y beat) int {
		if c := cmp.Compare(x.id, y.id); c != 0 {
			return c
		}
		return cmp.Compare(x.t, y.t)
	})
	var res []string
	for i := 1; i < n; i++ {
		if a[i].id == a[i-1].id && a[i].t-a[i-1].t > th && (len(res) == 0 || res[len(res)-1] != a[i].id) {
			res = append(res, a[i].id)
		}
	}
	out := strconv.AppendInt(nil, int64(len(res)), 10)
	out = append(out, '\n')
	for _, s := range res {
		out = append(out, s...)
		out = append(out, '\n')
	}
	os.Stdout.Write(out)
}
